#!/bin/sh
# Local only: the auth service's Ed25519 signing key, made once and kept in infra/secrets
# (git-ignored). Staging and production mount a key generated by the operator instead
# (TRD §15: secrets outside the repository, rotated yearly).
set -eu
key=/secrets/auth_signing_key.pem
if [ -s "$key" ]; then
  echo "dev signing key exists"
  exit 0
fi
openssl genpkey -algorithm ed25519 -out "$key"
# The service runs as uid 10001; a dev key may be world-readable inside the container.
chmod 644 "$key"
echo "dev signing key created"
